static std::vector<uint8_t> Bytes(const std::vector<uint32_t>&v){std::vector<uint8_t>b(v.size()*4);std::memcpy(b.data(),v.data(),b.size());return b;}
struct Buf{Api&a;void*p=nullptr;size_t n;Buf(Api&x,const std::vector<uint8_t>&v):a(x),n(v.size()){a.Check(a.hipMalloc(&p,n),"alloc");try{a.Check(a.hipMemcpy(p,v.data(),n,1),"upload");}catch(...){a.hipFree(p);p=nullptr;throw;}}~Buf(){if(p)a.hipFree(p);}std::vector<uint8_t>Read(){std::vector<uint8_t>v(n);a.Check(a.hipMemcpy(v.data(),p,n,2),"read");return v;}void*At(size_t o){return static_cast<uint8_t*>(p)+o;}};
static void Save(const std::filesystem::path&p,const std::vector<uint8_t>&v){std::ofstream f(p,std::ios::binary);if(!f||!f.write(reinterpret_cast<const char*>(v.data()),v.size()))throw std::runtime_error("write raw");}
static uint32_t U32(const std::vector<uint8_t>&v,size_t index){uint32_t x;std::memcpy(&x,v.data()+guard+index*4,4);return x;}
static size_t Guards(const std::vector<uint8_t>&v){size_t n=0;for(size_t i=0;i<guard;i++){n+=v[i]!=0xa5;n+=v[v.size()-guard+i]!=0xa5;}return n;}
static std::vector<uint8_t> Output(size_t words){std::vector<uint8_t>v(words*4+guard*2,0xa5);std::fill(v.begin()+guard,v.end()-guard,0xcd);return v;}
